def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_c = 0
    my_c = 0
    for a, b in history:
        if a == 'C':
            my_c += 1
        if b == 'C':
            opp_c += 1

    opp_d = n - opp_c
    my_d = n - my_c
    last_my, last_opp = history[-1]

    my_D_streak = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'D':
        my_D_streak += 1
        i -= 1

    opp_D_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        opp_D_streak += 1
        i -= 1

    r_len = 12 if n >= 12 else n
    recent_c = 0
    for i in range(n - r_len, n):
        if history[i][1] == 'C':
            recent_c += 1

    total_coop = opp_c / float(n)
    recent_coop = recent_c / float(r_len)

    if opp_c == 0 or (n >= 25 and opp_c <= 2):
        return 'D'

    if recent_c == 0:
        if opp_c > 10 and opp_D_streak >= 5 and total_coop > 0.35 and rng.random() < 0.07:
            return 'C'
        return 'D'

    if opp_d == 0:
        if n < 10:
            return 'C'
        max_streak = 2
        if n >= 35:
            max_streak = 4
        if n >= 55:
            max_streak = 6
        if n >= 80:
            max_streak = 1000
        if my_D_streak < max_streak:
            return 'D'
        return 'C'

    after_d = 0
    after_d_c = 0
    after_d_all = 0
    soft_punish_all = 0
    start = max(1, n - 30)
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            after_d_all += 1
            if history[i][1] == 'D':
                soft_punish_all += 1
            if i >= start:
                after_d += 1
                if history[i][1] == 'C':
                    after_d_c += 1

    if after_d:
        soft = after_d_c / float(after_d)
    else:
        soft = 0.5 + 0.5 * total_coop

    if after_d_all:
        soft_all = soft_punish_all / float(after_d_all)
    else:
        soft_all = 0.5

    if last_opp == 'C':
        if total_coop < 0.35 and recent_coop < 0.5:
            return 'D'

        if total_coop >= 0.55 and recent_coop >= 0.45:
            max_streak = 2

            if after_d == 0:
                if total_coop >= 0.8:
                    max_streak = 2
                else:
                    max_streak = 1
            else:
                if after_d >= 1 and soft <= 0.34:
                    max_streak = 0
                elif after_d_all >= 4 and soft_all <= 0.4:
                    max_streak = 0
                elif soft <= 0.25:
                    max_streak = 1
                elif soft < 0.45:
                    max_streak = 2
                elif soft < 0.65:
                    max_streak = 3
                elif soft < 0.8:
                    max_streak = 4 if total_coop >= 0.75 else 3
                elif soft < 0.9:
                    max_streak = 7 if total_coop >= 0.85 else 5
                else:
                    max_streak = 15 if total_coop >= 0.93 else 8

            if n > 80 and total_coop > 0.7:
                max_streak += 2

            if opp_d <= 5 and my_d > opp_d + 12 and n < 80:
                max_streak = min(max_streak, 2)

            if my_D_streak < max_streak:
                if after_d == 0 and total_coop < 0.85 and rng.random() < 0.5:
                    return 'C'
                return 'D'

        if my_c > opp_c + 8 and total_coop < 0.7:
            return 'D'

        return 'C'

    if last_opp == 'D':
        if last_my == 'D':
            if recent_c >= 8 and total_coop > 0.65 and opp_D_streak <= 3:
                return 'C'
            if recent_c >= 5 and total_coop > 0.5 and opp_D_streak >= 4:
                if rng.random() < 0.35:
                    return 'C'
            if recent_c >= 8 and total_coop > 0.7 and rng.random() < 0.45:
                return 'C'
            if recent_c >= 2 and total_coop > 0.35 and rng.random() < 0.12:
                return 'C'
            return 'D'

        if recent_c >= 10 and total_coop > 0.75:
            if rng.random() < 0.55:
                return 'C'
        if recent_c >= 7 and total_coop > 0.5:
            if rng.random() < 0.35:
                return 'C'
        if opp_D_streak == 1 and soft >= 0.5 and total_coop > 0.7:
            if rng.random() < 0.5:
                return 'C'
        if recent_c >= 11 and total_coop > 0.85 and rng.random() < 0.7:
            return 'C'

        return 'D'
